# Generated by build.py from recipe.yml for recipe smtp-catch-every-address-in-one-mailbox. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'invite.eml'), "From: app@example.com`nSubject: You are invited`n`nFollow the link to join.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'catchall@example.com:catchpass', '--mail-catch-all', 'example.com=catchall@example.com', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt user-1@example.com -T invite.eml smtp://127.0.0.1:8080/example.com --next --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt user-2@example.com -T invite.eml smtp://127.0.0.1:8080/example.com --next -u catchall@example.com:catchpass pop3://127.0.0.1:8081/ } finally { Stop-Process $server0 }
